import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { S3Client, PutObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3';
import type { Env } from '../../config/env.js';

/**
 * Blob storage for the installation (one per deployment: a local volume for Docker
 * Compose, the installation's own S3 bucket on AWS). Keys are generated by the
 * application only: <org-id>/(employees/<employee-id>|company)/<uuid>.
 */
export interface BlobStore {
  driver: 'local' | 's3';
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer>;
}

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const KEY_RE = new RegExp(`^${UUID}/(employees/${UUID}|company|expenses/${UUID}|policies)/${UUID}$`);
export function assertKey(key: string) { if (!KEY_RE.test(key)) throw new Error('invalid storage key'); }
export function newKey(tenantId: string, employeeId: string | null, area: 'documents' | 'expenses' | 'policies' = 'documents') {
  const key = area === 'policies' ? `${tenantId}/policies/${randomUUID()}` : area === 'expenses' ? `${tenantId}/expenses/${employeeId}/${randomUUID()}` : `${tenantId}/${employeeId ? `employees/${employeeId}` : 'company'}/${randomUUID()}`;
  assertKey(key);
  return key;
}

export class LocalStore implements BlobStore {
  driver = 'local' as const;
  private root: string;
  constructor(root: string) { this.root = path.resolve(root); }
  private file(key: string) {
    assertKey(key);
    const p = path.resolve(this.root, key);
    if (!p.startsWith(this.root + path.sep)) throw new Error('invalid storage path');
    return p;
  }
  async put(key: string, data: Buffer) {
    const p = this.file(key);
    await mkdir(path.dirname(p), { recursive: true, mode: 0o700 });
    const tmp = `${p}.${randomUUID()}.tmp`;
    await writeFile(tmp, data, { mode: 0o600, flag: 'wx' });
    await rename(tmp, p); // atomic: readers never see a partial file
  }
  async get(key: string) { return readFile(this.file(key)); }
}

export class S3Store implements BlobStore {
  driver = 's3' as const;
  private client: S3Client;
  constructor(private bucket: string, region: string) { this.client = new S3Client({ region }); }
  async put(key: string, data: Buffer, contentType: string) {
    assertKey(key);
    // Bucket default encryption is SSE-KMS with the installation key; requested explicitly as well.
    await this.client.send(new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: data, ContentType: contentType, ServerSideEncryption: 'aws:kms' }));
  }
  async get(key: string) {
    assertKey(key);
    const r = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    return Buffer.from(await r.Body!.transformToByteArray());
  }
}

let store: BlobStore | null = null;
export const setStore = (s: BlobStore | null) => { store = s; };
export const getStore = () => store;

export function createStore(env: Env): BlobStore | null {
  if (env.STORAGE_DRIVER === 'local') return new LocalStore(env.STORAGE_PATH!);
  if (env.STORAGE_DRIVER === 's3') return new S3Store(env.AWS_S3_BUCKET!, env.AWS_REGION!);
  return null;
}
